package com.bank.settlement.model;

import jakarta.persistence.*;
import java.math.BigDecimal;

@Entity
@Table(name = "trades")
public class Trade {
    @Id @Column(name = "trade_id") private String tradeId;
    @Column(name = "account_id") private String accountId;
    private String symbol;
    private BigDecimal amount;
    private String status;

    protected Trade() {}

    public Trade(String tradeId, String accountId, String symbol, BigDecimal amount, String status) {
        this.tradeId = tradeId; this.accountId = accountId; this.symbol = symbol;
        this.amount = amount; this.status = status;
    }

    public String getTradeId() { return tradeId; }
    public String getAccountId() { return accountId; }
    public String getSymbol() { return symbol; }
    public BigDecimal getAmount() { return amount; }
    public String getStatus() { return status; }
}
```

