// SERVICE — depends on TradeRepository INTERFACE, NOT on JPA/EntityManager
package com.bank.settlement.service;

import com.bank.settlement.dto.SettlementSummary;
import com.bank.settlement.model.Trade;
import com.bank.settlement.repository.TradeRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.util.List;

@Service
@RequiredArgsConstructor
@Slf4j
public class SettlementService {

    private final TradeRepository tradeRepo;  // INTERFACE — mockable, swappable

    // NO EntityManager, NO JPQL, NO SQL in this class!
    // All data access delegated to the repository.

    @Transactional(readOnly = true)
    public SettlementSummary getSettlementSummary(String accountId) {
        List<Trade> settled = tradeRepo.findByAccountIdAndStatus(accountId, "SETTLED");

        BigDecimal total = settled.stream()
            .map(Trade::getAmount)
            .reduce(BigDecimal.ZERO, BigDecimal::add);

        long count = settled.size();
        boolean hasSettled = !settled.isEmpty();

        log.info("Account {} — {} settled trades totaling Rs.{}", accountId, count, total);

        return new SettlementSummary(accountId, count, total, hasSettled);
    }
}
```

