// UNIT TEST — mocks repository, NO database needed!
package com.bank.settlement.service;

import com.bank.settlement.dto.SettlementSummary;
import com.bank.settlement.model.Trade;
import com.bank.settlement.repository.TradeRepository;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.*;
import org.mockito.junit.jupiter.MockitoExtension;
import java.math.BigDecimal;
import java.util.List;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
class SettlementServiceTest {

    @Mock TradeRepository tradeRepo;  // MOCK — no database!
    @InjectMocks SettlementService service;

    @Test
    void shouldCalculateSettledTotal() {
        // Arrange — mock returns test data
        when(tradeRepo.findByAccountIdAndStatus("SAV2001", "SETTLED"))
            .thenReturn(List.of(
                new Trade("T1", "SAV2001", "RELIANCE", new BigDecimal("100"), "SETTLED"),
                new Trade("T2", "SAV2001", "TCS", new BigDecimal("200"), "SETTLED")));

        // Act
        SettlementSummary summary = service.getSettlementSummary("SAV2001");

        // Assert
        assertThat(summary.settledCount()).isEqualTo(2);
        assertThat(summary.settledTotal()).isEqualByComparingTo("300");
        assertThat(summary.hasSettledTrades()).isTrue();
        // NO DATABASE! Test runs in 10ms, not 5 seconds.
    }

    @Test
    void shouldReturnZeroForNoSettledTrades() {
        when(tradeRepo.findByAccountIdAndStatus("SAV9999", "SETTLED"))
            .thenReturn(List.of());

        SettlementSummary summary = service.getSettlementSummary("SAV9999");

        assertThat(summary.settledCount()).isZero();
        assertThat(summary.settledTotal()).isEqualByComparingTo("0");
        assertThat(summary.hasSettledTrades()).isFalse();
    }
}
```

