// INTEGRATION TEST — tests actual JPA queries with @DataJpaTest
package com.bank.settlement.repository;

import com.bank.settlement.model.Trade;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.orm.jpa.DataJpaTest;
import org.springframework.boot.test.autoconfigure.orm.jpa.TestEntityManager;
import java.math.BigDecimal;
import java.util.List;
import static org.assertj.core.api.Assertions.*;

@DataJpaTest  // loads only JPA layer — no web, no service
class TradeRepositoryTest {

    @Autowired TradeRepository tradeRepo;
    @Autowired TestEntityManager em;

    @Test
    void shouldFindSettledTradesForAccount() {
        em.persist(new Trade("T1", "ACC1", "RELIANCE", new BigDecimal("100"), "SETTLED"));
        em.persist(new Trade("T2", "ACC1", "TCS", new BigDecimal("200"), "PENDING"));
        em.persist(new Trade("T3", "ACC1", "HDFC", new BigDecimal("300"), "SETTLED"));
        em.flush();

        List<Trade> settled = tradeRepo.findByAccountIdAndStatus("ACC1", "SETTLED");

        assertThat(settled).hasSize(2);
        assertThat(settled).extracting(Trade::getSymbol).containsExactlyInAnyOrder("RELIANCE", "HDFC");
    }
}
```
